package com.bank;import java.util.*;public class Customer{private final int customerId;private String name,email,city,phone,customerType;public Customer(int id,String n,String e,String c,String p,String t){customerId=id;name=n;email=e;city=c;phone=p;customerType=t;}public int getCustomerId(){return customerId;}public String getName(){return name;}public String getEmail(){return email;}public String getCity(){return city;}public String getPhone(){return phone;}public String getCustomerType(){return customerType;}public void setName(String x){name=x;}public void setEmail(String x){email=x;}public void setCity(String x){city=x;}public void setPhone(String x){phone=x;}public void setCustomerType(String x){customerType=x;}public boolean equals(Object o){return o instanceof Customer c&&c.customerId==customerId;}public int hashCode(){return Objects.hash(customerId);}public String toString(){return customerId+" | "+name+" | "+email+" | "+city+" | "+phone+" | "+customerType;}}
